    random.seed(seed)

    def generate_formula(n):
        if n == 1:
            return 'x'
        else:
            subformulas = [generate_formula(n - 1) for _ in range(2)]
            return f'({subformulas[0]} & {subformulas[1]}) | ({subformulas[0]} ^ {subformulas[1]})'

    def evaluate_formula(formula):
        if formula == 'x':
            return random.choice([True, False])
        elif formula.startswith('(') and formula.endswith(')'):
            subformula = formula[1:-1]
            if subformula.startswith('(') and subformula.endswith(')'):
                left, right = subformula.split(' & ')
                return evaluate_formula(left) and evaluate_formula(right)
            else:
                left, operator, right = subformula.split()
                if operator == '|':
                    return evaluate_formula(left) or evaluate_formula(right)
                elif operator == '^':
                    return evaluate_formula(left) != evaluate_formula(right)
        else:
            raise ValueError("Invalid formula")

    def tropical_norm(formula):
        if formula == 'x':
            return 1
        elif formula.startswith('(') and formula.endswith(')'):
            subformula = formula[1:-1]
            if subformula.startswith('(') and subformula.endswith(')'):
                left, right = subformula.split(' & ')
                return max(tropical_norm(left), tropical_norm(right))
            else:
                left, operator, right = subformula.split()
                if operator == '|':
                    return max(tropical_norm(left), tropical_norm(right))
                elif operator == '^':
                    return 1 + max(tropical_norm(left), tropical_norm(right))
        else:
            raise ValueError("Invalid formula")

    def resolution_length(formula):
        if formula == 'x':
            return 1
        elif formula.startswith('(') and formula.endswith(')'):
            subformula = formula[1:-1]
            if subformula.startswith('(') and subformula.endswith(')'):
                left, right = subformula.split(' & ')
                return resolution_length(left) + resolution_length(right)
            else:
                left, operator, right = subformula.split()
                if operator == '|':
                    return max(resolution_length(left), resolution_length(right))
                elif operator == '^':
                    return 1 + max(resolution_length(left), resolution_length(right))
        else:
            raise ValueError("Invalid formula")

    n = random.choice([5, 10, 15, 20, 30, 40])
    formula = generate_formula(n)
    if not evaluate_formula(formula):
        return {
            "metric_name": "tropical_norm",
